def solution(s):
    s = s.lstrip()
    if not s:
        return 0
    sign = 1
    idx = 0
    if s[0] == '-':
        sign = -1
        idx += 1
    elif s[0] == '+':
        idx += 1
    num = 0
    INT_MAX = 2**31 - 1
    INT_MIN = -2**31
    while idx < len(s) and s[idx].isdigit():
        num = num * 10 + int(s[idx])
        idx += 1
    num *= sign
    if num > INT_MAX:
        return INT_MAX
    if num < INT_MIN:
        return INT_MIN
    return num
